def build(n):
    # Deterministic forbidden-cycle-optimised cubic configuration construction.
    if n not in (20, 26, 30):
        raise ValueError("supported values are 20, 26, and 30")

    state = (0xD1B54A35 ^ (n * 0x9E3779B9)) & 0xffffffff

    def rnd(k):
        nonlocal state
        state ^= (state << 13) & 0xffffffff
        state ^= state >> 17
        state ^= (state << 5) & 0xffffffff
        state &= 0xffffffff
        return state % k

    def cycle8(adj):
        total = 0

        def dfs(start, v, depth, used):
            nonlocal total
            if depth == 8:
                if start in adj[v]:
                    total += 1
                return
            for w in adj[v]:
                if w > start and not (used >> w) & 1:
                    dfs(start, w, depth + 1, used | (1 << w))

        for s in range(n):
            for v in adj[s]:
                if v > s:
                    dfs(s, v, 2, (1 << s) | (1 << v))
        return total // 2

    def cycle4(adj):
        total = 0
        for a in range(n):
            for b in range(a + 1, n):
                k = len(adj[a] & adj[b])
                total += k * (k - 1) // 2
        return total // 2

    def score(adj):
        a = cycle4(adj)
        if a:
            return a * 1000, a, 0
        b = cycle8(adj)
        return b, 0, b

    def random_cubic():
        while True:
            stubs = []
            for v in range(n):
                stubs.extend((v, v, v))
            for i in range(len(stubs) - 1, 0, -1):
                j = rnd(i + 1)
                stubs[i], stubs[j] = stubs[j], stubs[i]

            adj = [set() for _ in range(n)]
            edges = []
            good = True
            for i in range(0, len(stubs), 2):
                a, b = stubs[i], stubs[i + 1]
                if a == b or b in adj[a]:
                    good = False
                    break
                adj[a].add(b)
                adj[b].add(a)
                edges.append((a, b))
            if good:
                return adj, edges

    best_adj = None
    best_value = 10 ** 9

    for restart in range(36):
        adj, edges = random_cubic()
        value, c4, c8 = score(adj)

        if value < best_value:
            best_value = value
            best_adj = [set(x) for x in adj]
        if c4 == 0 and c8 <= 1:
            return [sorted(x) for x in adj]

        temperature = 24

        for step in range(1100):
            i = rnd(len(edges))
            j = rnd(len(edges) - 1)
            if j >= i:
                j += 1

            a, b = edges[i]
            c, d = edges[j]
            if len({a, b, c, d}) != 4:
                continue

            if rnd(2):
                x, y, u, v = a, c, b, d
            else:
                x, y, u, v = a, d, b, c

            if y in adj[x] or v in adj[u]:
                continue

            adj[a].remove(b)
            adj[b].remove(a)
            adj[c].remove(d)
            adj[d].remove(c)
            adj[x].add(y)
            adj[y].add(x)
            adj[u].add(v)
            adj[v].add(u)

            new_value, new_c4, new_c8 = score(adj)
            delta = new_value - value
            accept = delta <= 0

            if not accept:
                t = max(1, temperature)
                accept = rnd(4096) < (4096 * t // (t + 80 * delta))

            if accept:
                edges[i] = (x, y)
                edges[j] = (u, v)
                value, c4, c8 = new_value, new_c4, new_c8

                if value < best_value:
                    best_value = value
                    best_adj = [set(z) for z in adj]

                if c4 == 0 and c8 <= 1:
                    return [sorted(z) for z in adj]
            else:
                adj[x].remove(y)
                adj[y].remove(x)
                adj[u].remove(v)
                adj[v].remove(u)
                adj[a].add(b)
                adj[b].add(a)
                adj[c].add(d)
                adj[d].add(c)

            if step % 46 == 45 and temperature > 1:
                temperature -= 1

    return [sorted(x) for x in best_adj]
